// The handwritten signature of Joelison Alves Marinho, the course's
// instructor, for the certificate PDF only. Cut from a photo the user sent
// on 07/11/2026, background removed, levelled (rotated 5.3°) so its long
// stroke is straight. That stroke sits at 51.5% of the height:
// the PDF puts that point on the signature line.
//
// A module, not a file under public/: it must never be served on its own,
// and a module rides in the server bundle with no file tracing to set up.

/** Width and height of the PNG, in pixels. */
export const SIGNATURE_SIZE = { width: 517, height: 300 } as const;

/** Where the long horizontal stroke sits, as a share of the height. */
export const SIGNATURE_BASELINE = 0.515;

export const SIGNATURE_PNG_BASE64 =
  "";
